import { authed, db, json, readJson } from "@/server/http/api";
import { punchIn } from "@/server/services/attendance";

/** Body: { location, notes? }. The timestamp is generated by the server. */
export const POST = authed(async ({ req, actor, ctx }) => json({ session: await punchIn(db, actor, await readJson(req), ctx) }, { status: 201 }));
